sampler sampler_pw_noise_lq;
float z, h1;
vec2 rs, uv1, uv2, uv3;
vec3 noise, ret1, ret2, rets;

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uv1 = (uv-.5);//*uAspect.xy;
h1 = .2;
z = h1/abs(pow(uv1.y, 1.0 ));
rs.x = uv1.x * z;
rs.y = z / 2.0 + uTime * 4.0;
noise = texture(sampler_noise_hq,rs);
noise *= (noise >= .0);
ret1 = noise-.6;
uv2 = 1.0 * uv1 * (1.0 - abs(uv1.x)) ;
float mask = clamp01(128.0 * uv1.y);
uv3 =fract(uv2-.5-ret1*.05* mask);
ret1 = texture(sampler_main, uv3) +
.02/(.02+length(uv3.y-.52))*slow_roam_sin;
vec2 uv2 = 32.0 * (multiply(uv,mat2(.6,.8,-.8,.6))+ret1*.1+uTime / 64.0);
vec3 smask = (texture(sampler_pw_noise_lq,uv2 / 256.0)).g-.9;
float stars = clamp01(.25/length(abs(fract(uv2)-.5))*smask);
ret = ret1* (1+0*lum(ret1)) + (stars*stars +rand_preset*(.5-uv.y)*vec3 ( 0.0 , 0.0 , 1.0 ))* (1.0 - mask);
ret*=.82*(GetPixel (uv_orig))-.29*(ret*max((1.0 - GetPixel (uv_orig)),.16*(1.0 - uv.y*(.2+uv.x))));
  fragColor = vec4(ret, 1.0);
}

